INSERT INTO public.assessments (id, tier, pair_id, prompt, option_a_text, option_a_competency, option_b_text, option_b_competency)
VALUES
('ic_1.1', 'ic', '1.1', 'When wrapping up a key deliverable, I ensure that I...', 'Produce thorough, error-free work.', 'High-Quality Delivery', 'Openly convey progress and insights to the team.', 'Transparent Sharing'),
('ic_1.2', 'ic', '1.2', 'When a process unexpectedly breaks down, my first reflex is to...', 'Openly communicate the issue so no one is in the dark.', 'Transparent Sharing', 'Pinpoint the root causes of the tactical friction.', 'Roadblock Diagnosis'),
('ic_1.3', 'ic', '1.3', 'When tasked with a complex assignment, my strength lies in...', 'Diagnosing the core bottleneck preventing progress.', 'Roadblock Diagnosis', 'Applying domain knowledge and specialized tools with high precision.', 'Technical Mastery'),
('ic_1.4', 'ic', '1.4', 'I am most valued by my team for my ability to...', 'Execute highly technical work with precision.', 'Technical Mastery', 'Take full end-to-end responsibility for the outcome.', 'Ownership Mindset'),
('ic_1.5', 'ic', '1.5', 'When an urgent project falls behind schedule, my instinct is to...', 'Take end-to-end responsibility for orchestrating the next steps.', 'Ownership Mindset', 'Work swiftly and eliminate unnecessary bottlenecks.', 'Execution Efficiency'),
('ic_1.6', 'ic', '1.6', 'In a fast-paced work environment, I pride myself on...', 'Eliminating bottlenecks in my daily tasks.', 'Execution Efficiency', 'Attentively processing peer perspectives before reacting.', 'Active Listening'),
('ic_1.7', 'ic', '1.7', 'When a teammate comes to me with a challenge, my natural response is to...', 'Attentively process their perspective before formulating a response.', 'Active Listening', 'Implement lean, pragmatic fixes that address the immediate issue.', 'Practical Solutions'),
('ic_1.8', 'ic', '1.8', 'To ensure I remain highly effective, I focus on...', 'Implementing lean, pragmatic fixes for immediate challenges.', 'Practical Solutions', 'Keeping my technical capabilities current through practice.', 'Continuous Learning'),
('ic_1.9', 'ic', '1.9', 'After a project concludes, I am most likely to...', 'Research new methods to keep my capabilities current.', 'Continuous Learning', 'Transparently acknowledge missteps to turn them into improvements.', 'Constructive Correction'),
('ic_1.10', 'ic', '1.10', 'When reviewing my recent performance, I prioritize...', 'Acknowledging personal missteps openly.', 'Constructive Correction', 'Meeting deadlines dependably and communicating milestones.', 'Timeline Reliability'),
('ic_1.11', 'ic', '1.11', 'To keep team initiatives moving smoothly, I consistently...', 'Meet deadlines dependably and proactively communicate milestones.', 'Timeline Reliability', 'Foster positive, supportive working relationships across my immediate circle.', 'Constructive Teaming'),
('ic_1.12', 'ic', '1.12', 'When collaborating on a cross-functional task, I focus on...', 'Fostering positive, supportive relationships.', 'Constructive Teaming', 'Resolving issues cleanly within agreed operational boundaries.', 'Scoped Execution'),
('ic_1.13', 'ic', '1.13', 'When navigating ambiguous project requirements, my priority is to...', 'Execute cleanly within the agreed operational parameters.', 'Scoped Execution', 'Uphold specialized quality benchmarks in my outputs.', 'Quality Standards'),
